        // OIIO::clamp for a Dual2 (compares the values only)
        private static Dual2f spline_clamp(Dual2f a, Dual2f low, Dual2f high)
        {
            Dual2f val = a;
            if (!(low.x <= val.x)) // Forces clamp(NaN,low,high) to return low
            {
                val = low;
            }
            if (val.x > high.x)
            {
                val = high;
            }
            return val;
        }

        // OIIO::lerp and OIIO::invert (fmath.h): the Regula Falsi root finder used by splineinverse, for floats and for Dual2 floats
        private static Dual2f spline_lerp(Dual2f v0, Dual2f v1, Dual2f x)
        {
            return v0 * (new Dual2f(1.0f) - x) + v1 * x;
        }

        private static Dual2f spline_fabs(Dual2f x)
        {
            return x.x >= 0.0f ? x : -x;
        }

        private static float spline_invert_f(ulong basis_name, float* knots, int knot_count, int knot_arraylen, float y, float xmin, float xmax, int maxiters, float eps, out bool brack)
        {
            // Use the Regula Falsi method, falling back to bisection if it hasn't converged after 3/4 of the maximum number of iterations.
            float v0 = spline_func_f(basis_name, knots, knot_count, knot_arraylen, xmin);
            float v1 = spline_func_f(basis_name, knots, knot_count, knot_arraylen, xmax);
            float x = xmin;
            float v = v0;
            bool increasing = (v0 < v1);
            float vmin = increasing ? v0 : v1;
            float vmax = increasing ? v1 : v0;
            bool bracketed = (y >= vmin && y <= vmax);
            brack = bracketed;
            if (!bracketed)
            {
                // If our bounds don't bracket the zero, just give up, and return the appropriate "edge" of the interval
                return ((y < vmin) == increasing) ? xmin : xmax;
            }
            if (MathF.Abs(v0 - v1) < eps) // already close enough
            {
                return x;
            }
            int rfiters = (3 * maxiters) / 4; // how many times to try regula falsi
            for (int iters = 0; iters < maxiters; ++iters)
            {
                float t; // interpolation factor
                if (iters < rfiters)
                {
                    // Regula falsi
                    t = (y - v0) / (v1 - v0);
                    if (t <= 0.0f || t >= 1.0f)
                    {
                        t = 0.5f; // RF convergence failure -- bisect instead
                    }
                }
                else
                {
                    t = 0.5f; // bisection
                }
                x = fmath.lerp(xmin, xmax, t);
                v = spline_func_f(basis_name, knots, knot_count, knot_arraylen, x);
                if ((v < y) == increasing)
                {
                    xmin = x;
                    v0 = v;
                }
                else
                {
                    xmax = x;
                    v1 = v;
                }
                if (MathF.Abs(xmax - xmin) < eps || MathF.Abs(v - y) < eps)
                {
                    return x; // converged
                }
            }
            return x;
        }

        private static Dual2f spline_invert_df(ulong basis_name, float* knots, int knot_count, int knot_arraylen, Dual2f y, Dual2f xmin, Dual2f xmax, int maxiters, Dual2f eps, out bool brack)
        {
            // Use the Regula Falsi method, falling back to bisection if it hasn't converged after 3/4 of the maximum number of iterations.
            Dual2f v0 = spline_func_df(basis_name, knots, knot_count, knot_arraylen, xmin);
            Dual2f v1 = spline_func_df(basis_name, knots, knot_count, knot_arraylen, xmax);
            Dual2f x = xmin;
            Dual2f v = v0;
            bool increasing = (v0.x < v1.x);
            Dual2f vmin = increasing ? v0 : v1;
            Dual2f vmax = increasing ? v1 : v0;
            bool bracketed = (y.x >= vmin.x && y.x <= vmax.x);
            brack = bracketed;
            if (!bracketed)
            {
                // If our bounds don't bracket the zero, just give up, and return the appropriate "edge" of the interval
                return ((y.x < vmin.x) == increasing) ? xmin : xmax;
            }
            if (spline_fabs(v0 - v1).x < eps.x) // already close enough
            {
                return x;
            }
            int rfiters = (3 * maxiters) / 4; // how many times to try regula falsi
            for (int iters = 0; iters < maxiters; ++iters)
            {
                Dual2f t; // interpolation factor
                if (iters < rfiters)
                {
                    // Regula falsi
                    t = (y - v0) / (v1 - v0);
                    if (t.x <= 0.0f || t.x >= 1.0f)
                    {
                        t = new Dual2f(0.5f); // RF convergence failure -- bisect instead
                    }
                }
                else
                {
                    t = new Dual2f(0.5f); // bisection
                }
                x = spline_lerp(xmin, xmax, t);
                v = spline_func_df(basis_name, knots, knot_count, knot_arraylen, x);
                if ((v.x < y.x) == increasing)
                {
                    xmin = x;
                    v0 = v;
                }
                else
                {
                    xmax = x;
                    v1 = v;
                }
                if (spline_fabs(xmax - xmin).x < eps.x || spline_fabs(v - y).x < eps.x)
                {
                    return x; // converged
                }
            }
            return x;
        }

        // SplineFunctor<float, float> and SplineFunctor<Dual2<float>, Dual2<float>>
        private static float spline_func_f(ulong basis_name, float* knots, int knot_count, int knot_arraylen, float x)
        {
            float v;
            spline_evaluate_fff(basis_name, &v, x, knots, knot_count, knot_arraylen);
            return v;
        }

        private static Dual2f spline_func_df(ulong basis_name, float* knots, int knot_count, int knot_arraylen, Dual2f x)
        {
            Dual2f v;
            spline_evaluate_dfdff(basis_name, &v, x, knots, knot_count, knot_arraylen);
            return v;
        }

        // SplineInterp::inverse<float>
        private static void spline_inverse_f(ulong basis_name, float* x, float y, float* knots, int knot_count, int knot_arraylen)
        {
            int basis_step = spline_basis_step[spline_basis_type_of(basis_name)];
            // account for out-of-range inputs, just clamp to the values we have
            int lowindex = basis_step == 1 ? 1 : 0;
            int highindex = basis_step == 1 ? knot_count - 2 : knot_count - 1;
            bool increasing = knots[1] < knots[knot_count - 2];
            if (increasing)
            {
                if (y <= knots[lowindex])
                {
                    *x = 0.0f;
                    return;
                }
                if (y >= knots[highindex])
                {
                    *x = 1.0f;
                    return;
                }
            }
            else
            {
                if (y >= knots[lowindex])
                {
                    *x = 0.0f;
                    return;
                }
                if (y <= knots[highindex])
                {
                    *x = 1.0f;
                    return;
                }
            }

            // Because of the nature of spline interpolation, monotonic knots can still lead to a non-monotonic curve. To deal with this,
            // search separately on each spline segment and hope for the best.
            int nsegs = (knot_count - 4) / basis_step + 1;
            float nseginv = 1.0f / nsegs;
            float r0 = 0.0f;
            *x = 0.0f;
            for (int s = 0; s < nsegs; ++s) // Search each interval
            {
                float r1 = nseginv * (s + 1);
                bool brack;
                *x = spline_invert_f(basis_name, knots, knot_count, knot_arraylen, y, r0, r1, 32, 1.0e-6f, out brack);
                if (brack)
                {
                    return;
                }
                r0 = r1; // Start of next interval is end of this one
            }
        }

        // SplineInterp::inverse<Dual2f>
        private static void spline_inverse_df(ulong basis_name, Dual2f* x, Dual2f y, float* knots, int knot_count, int knot_arraylen)
        {
            int basis_step = spline_basis_step[spline_basis_type_of(basis_name)];
            // account for out-of-range inputs, just clamp to the values we have
            int lowindex = basis_step == 1 ? 1 : 0;
            int highindex = basis_step == 1 ? knot_count - 2 : knot_count - 1;
            bool increasing = knots[1] < knots[knot_count - 2];
            if (increasing)
            {
                if (y.x <= knots[lowindex])
                {
                    *x = new Dual2f(0.0f);
                    return;
                }
                if (y.x >= knots[highindex])
                {
                    *x = new Dual2f(1.0f);
                    return;
                }
            }
            else
            {
                if (y.x >= knots[lowindex])
                {
                    *x = new Dual2f(0.0f);
                    return;
                }
                if (y.x <= knots[highindex])
                {
                    *x = new Dual2f(1.0f);
                    return;
                }
            }

            // Because of the nature of spline interpolation, monotonic knots can still lead to a non-monotonic curve. To deal with this,
            // search separately on each spline segment and hope for the best.
            int nsegs = (knot_count - 4) / basis_step + 1;
            float nseginv = 1.0f / nsegs;
            Dual2f r0 = new Dual2f(0.0f);
            *x = new Dual2f(0.0f);
            for (int s = 0; s < nsegs; ++s) // Search each interval
            {
                Dual2f r1 = new Dual2f(nseginv * (s + 1));
                bool brack;
                *x = spline_invert_df(basis_name, knots, knot_count, knot_arraylen, y, r0, r1, 32, new Dual2f(1.0e-6f), out brack);
                if (brack)
                {
                    return;
                }
                r0 = r1; // Start of next interval is end of this one
            }
        }

        public static void osl_spline_fff(void* out_, ulong spline, void* x, void* knots, int knot_count, int knot_arraylen)
        {
            spline_evaluate_fff(spline, (float*)out_, *(float*)x, (float*)knots, knot_count, knot_arraylen);
        }

