        public static void osl_splineinverse_fff(void* out_, ulong spline, void* x, void* knots, int knot_count, int knot_arraylen)
        {
            // Version with no derivs
            spline_inverse_f(spline, (float*)out_, *(float*)x, (float*)knots, knot_count, knot_arraylen);
        }

        public static void osl_splineinverse_dfdff(void* out_, ulong spline, void* x, void* knots, int knot_count, int knot_arraylen)
        {
            // x has derivs, so return derivs as well
            spline_inverse_df(spline, (Dual2f*)out_, *(Dual2f*)x, (float*)knots, knot_count, knot_arraylen);
        }

        public static void osl_splineinverse_dfdfdf(void* out_, ulong spline, void* x, void* knots, int knot_count, int knot_arraylen)
        {
            // Ignore knot derivatives
            osl_splineinverse_dfdff(out_, spline, x, (float*)knots, knot_count, knot_arraylen);
        }

        public static void osl_splineinverse_dffdf(void* out_, ulong spline, void* x, void* knots, int knot_count, int knot_arraylen)
        {
            // Ignore knot derivs
            float outtmp = 0;
            osl_splineinverse_fff(&outtmp, spline, x, (float*)knots, knot_count, knot_arraylen);
            *(Dual2f*)out_ = new Dual2f(outtmp);
        }
    }
